export interface BrandAsset { body: string; type: string }

/** Every brand file the site serves, by path. All public, all immutable for a day. */
export const BRAND_ASSETS: Readonly<Record<string, BrandAsset>> = {
  "/brand/ecdysis-horizontal-light.svg": { body: LOGO_HORIZONTAL_LIGHT, type: "image/svg+xml; charset=utf-8" },
  "/brand/ecdysis-horizontal-dark.svg": { body: LOGO_HORIZONTAL_DARK, type: "image/svg+xml; charset=utf-8" },
  "/brand/ecdysis-symbol.svg": { body: LOGO_SYMBOL, type: "image/svg+xml; charset=utf-8" },
  "/favicon.svg": { body: FAVICON_SVG, type: "image/svg+xml; charset=utf-8" },
};

/** The headers a brand asset is served with: an image, cacheable, no script anywhere near it. */
export const BRAND_HEADERS: Readonly<Record<string, string>> = {
  "cache-control": "public, max-age=86400, immutable",
  "x-content-type-options": "nosniff",
  "content-security-policy": "default-src 'none'; style-src 'unsafe-inline'",
  "referrer-policy": "no-referrer",
  "strict-transport-security": "max-age=31536000; includeSubDomains",
};

/**
 * The lockup for the page header: light or dark by the reader's colour
 * scheme, as the kit asks, with the alt the kit specifies for a home link.
 * Width is set in CSS (240px desktop, 190px on phones); height stays
 * proportional. The symbol replaces it below 180px, also in CSS.
 */
export function brandLockup(alt = "Ecdysis home"): string {
  return `<picture><source media="(prefers-color-scheme: dark)" srcset="/brand/ecdysis-horizontal-dark.svg"><img class="lockup" src="/brand/ecdysis-horizontal-light.svg" alt="${alt}" width="740" height="190" decoding="async"></picture>` +
    `<img class="symbol" src="/brand/ecdysis-symbol.svg" alt="" width="540" height="258" decoding="async" aria-hidden="true">`;
}
